CREATE TRIGGER asset_file_release_candidate INSTEAD OF INSERT ON asset_file_release_candidates BEGIN
    INSERT INTO asset_file_retention_releases(logical_key,released_at,held)
  SELECT candidate.logical_key,CAST(unixepoch('subsec')*1000 AS INTEGER),0 FROM (SELECT NEW.logical_key AS logical_key) candidate WHERE candidate.logical_key IS NOT NULL AND NOT ((
  EXISTS(SELECT 1 FROM asset_file_reference_paths f WHERE f.path IN ('/r2-assets/'||candidate.logical_key,'/'||candidate.logical_key) AND EXISTS(SELECT 1 FROM asset_file_reference_inputs raw WHERE raw.row_table=f.row_table AND raw.row_id=json_extract(f.row_key,'$[0]') AND raw.row_key=f.row_key AND raw.field=f.field AND raw.raw_url=f.raw_url) AND NOT EXISTS(SELECT 1 FROM content_transitions t,json_each(t.plan_json,'$.fileOrigins') o WHERE json_extract(o.value,'$.origin')=f.origin AND json_extract(o.value,'$.kind')='external' AND ((f.row_table='notices' AND EXISTS(SELECT 1 FROM notices owner WHERE json_array(owner.id)=f.row_key AND ((EXISTS(SELECT 1 FROM json_each(t.plan_json,'$.classifications') decision WHERE json_extract(decision.value,'$.table')='notices' AND json_extract(decision.value,'$.key')=json_array(owner.id) AND json_extract(decision.value,'$.disposition')='include') OR (EXISTS(SELECT 1 FROM json_each(t.plan_json,'$.members') member WHERE iif(t.local_site=json_extract(t.plan_json,'$.sourceSite'),json_extract(member.value,'$.uid'),json_extract(member.value,'$.targetUid'))=owner.publisher_member_uid) OR EXISTS(SELECT 1 FROM json_each(owner.related_member_uids) related WHERE EXISTS(SELECT 1 FROM json_each(t.plan_json,'$.members') member WHERE iif(t.local_site=json_extract(t.plan_json,'$.sourceSite'),json_extract(member.value,'$.uid'),json_extract(member.value,'$.targetUid'))=related.value)))) AND NOT EXISTS(SELECT 1 FROM json_each(t.plan_json,'$.classifications') decision WHERE json_extract(decision.value,'$.table')='notices' AND json_extract(decision.value,'$.key')=json_array(owner.id) AND json_extract(decision.value,'$.disposition')='exclude')))) OR (f.row_table='member_profile_images' AND EXISTS(SELECT 1 FROM member_profile_images owner WHERE json_array(owner.id)=f.row_key AND ((EXISTS(SELECT 1 FROM json_each(t.plan_json,'$.classifications') decision WHERE json_extract(decision.value,'$.table')='member_profile_images' AND json_extract(decision.value,'$.key')=json_array(owner.id) AND json_extract(decision.value,'$.disposition')='include') OR EXISTS(SELECT 1 FROM json_each(t.plan_json,'$.members') member WHERE iif(t.local_site=json_extract(t.plan_json,'$.sourceSite'),json_extract(member.value,'$.uid'),json_extract(member.value,'$.targetUid'))=owner.member_uid)) AND NOT EXISTS(SELECT 1 FROM json_each(t.plan_json,'$.classifications') decision WHERE json_extract(decision.value,'$.table')='member_profile_images' AND json_extract(decision.value,'$.key')=json_array(owner.id) AND json_extract(decision.value,'$.disposition')='exclude')))) OR (f.row_table='naver_cafe_posts' AND EXISTS(SELECT 1 FROM naver_cafe_posts owner WHERE json_array(owner.id)=f.row_key AND ((EXISTS(SELECT 1 FROM json_each(t.plan_json,'$.classifications') decision WHERE json_extract(decision.value,'$.table')='naver_cafe_posts' AND json_extract(decision.value,'$.key')=json_array(owner.id) AND json_extract(decision.value,'$.disposition')='include') OR EXISTS(SELECT 1 FROM json_each(t.plan_json,'$.members') member WHERE iif(t.local_site=json_extract(t.plan_json,'$.sourceSite'),json_extract(member.value,'$.uid'),json_extract(member.value,'$.targetUid'))=owner.member_uid)) AND NOT EXISTS(SELECT 1 FROM json_each(t.plan_json,'$.classifications') decision WHERE json_extract(decision.value,'$.table')='naver_cafe_posts' AND json_extract(decision.value,'$.key')=json_array(owner.id) AND json_extract(decision.value,'$.disposition')='exclude'))))))) OR
  EXISTS(SELECT 1 FROM members m WHERE candidate.logical_key LIKE 'members/'||m.code||'/backgrounds/%')
) OR (
  EXISTS(SELECT 1 FROM content_transition_membership m JOIN content_transitions t ON t.id=m.transition_id WHERE t.phase<>'prepared' AND m.row_table='asset_file_references' AND m.row_key=json_array(candidate.logical_key)) OR
  EXISTS(SELECT 1 FROM (
    SELECT value, 0 AS historical FROM (SELECT raw.raw_url AS value FROM asset_file_reference_inputs raw
  WHERE NOT EXISTS(SELECT 1 FROM asset_file_reference_paths f WHERE f.row_table=raw.row_table AND f.row_key=raw.row_key AND f.field=raw.field AND f.raw_url=raw.raw_url))
    UNION ALL SELECT value, 1 FROM (SELECT image.atom AS value FROM content_transition_journal j,json_tree(j.before_json) image WHERE image.type='text'
  UNION ALL SELECT image.atom FROM content_transition_journal j,json_tree(j.after_json) image WHERE image.type='text'
  UNION ALL SELECT image.atom FROM content_transition_baseline_rows b,json_tree(b.record_json) image WHERE image.type='text'
  UNION ALL SELECT image.atom FROM content_historical_records h,json_tree(h.record_json) image WHERE image.type='text') LIMIT -1
  ) input WHERE (input.historical AND input.value=candidate.logical_key) OR (WITH RECURSIVE u(state,low,high,next) AS (VALUES (0,'00','7F',0),(0,'C2','DF',1),(0,'E0','E0',4),(0,'E1','EC',2),(0,'ED','ED',5),(0,'EE','EF',2),(0,'F0','F0',6),(0,'F1','F3',3),(0,'F4','F4',7),(1,'80','BF',0),(2,'80','BF',1),(3,'80','BF',2),(4,'A0','BF',1),(5,'80','9F',1),(6,'90','BF',2),(7,'80','8F',2)), p(x) AS MATERIALIZED (SELECT replace(replace(replace(replace(trim((SELECT iif(origin IS NULL,iif(substr(replace(replace(replace(replace(value,char(9),''),char(10),''),char(13),''),char(92),'/'),1,2)='//','/',value),substr(value,length(origin)+1)) FROM (SELECT trim(input.value) value,(SELECT iif(instr(v,'://')>0,substr(v,1,instr(v,'://')+1+instr(substr(v,instr(v,'://')+3)||'/','/')),iif(substr(v,1,2)='//',substr(v,1,1+instr(substr(v,3)||'/','/')),NULL)) FROM (SELECT trim(input.value) v)) origin))),char(9),''),char(10),''),char(13),''),char(92),'/')), n(r,a) AS (SELECT substr(substr(x,1,min(instr(x||'?','?'),instr(x||'#','#'))-1),2)||'/',json_array() FROM p WHERE substr(x,1,1)='/' UNION ALL SELECT substr(r,instr(r,'/')+1), CASE replace(lower(substr(r,1,instr(r,'/')-1)),'%2e','.') WHEN '.' THEN iif(instr(r,'/')=length(r),json_insert(a,'$[#]',''),a) WHEN '..' THEN iif(instr(r,'/')=length(r),json_insert(json_remove(a,'$[#-1]'),'$[#]',''),json_remove(a,'$[#-1]')) ELSE json_insert(a,'$[#]',substr(r,1,instr(r,'/')-1)) END FROM n WHERE r<>''), j(v) AS (SELECT '/'||COALESCE(group_concat(value,'/'),'') FROM n,json_each(a) WHERE r=''), d(r,v,n) AS (SELECT v,'',0 FROM j UNION ALL SELECT substr(r,iif(r GLOB '%[0-9A-Fa-f][0-9A-Fa-f]*',4,2)),v||iif(r GLOB '%[0-9A-Fa-f][0-9A-Fa-f]*',char((instr('0123456789ABCDEF',upper(substr(r,2,1)))-1)*16+instr('0123456789ABCDEF',upper(substr(r,3,1)))-1),substr(r,1,1)), iif(substr(r,1,1)<>'%',iif(n=0,0,-1),iif(r GLOB '%[0-9A-Fa-f][0-9A-Fa-f]*', coalesce((SELECT next FROM u WHERE state=d.n AND upper(substr(d.r,2,2)) BETWEEN low AND high),-1),-1)) FROM d WHERE r<>'' AND n>=0), e(x) AS MATERIALIZED (SELECT replace(replace(replace(replace(v,char(9),''),char(10),''),char(13),''),char(92),'/') FROM d WHERE r='' AND n=0), s(r,a) AS (SELECT substr(substr(x,1,min(instr(x||'?','?'),instr(x||'#','#'))-1),2)||'/',json_array() FROM e WHERE substr(x,1,1)='/' AND substr(x,1,2)<>'//' UNION ALL SELECT substr(r,instr(r,'/')+1), CASE substr(r,1,instr(r,'/')-1) WHEN '.' THEN iif(instr(r,'/')=length(r),json_insert(a,'$[#]',''),a) WHEN '..' THEN iif(instr(r,'/')=length(r),json_insert(json_remove(a,'$[#-1]'),'$[#]',''),json_remove(a,'$[#-1]')) ELSE json_insert(a,'$[#]',substr(r,1,instr(r,'/')-1)) END FROM s WHERE r<>'') SELECT '/'||COALESCE(group_concat(value,'/'),'') FROM s,json_each(a) WHERE r='') IN ('/r2-assets/'||candidate.logical_key,'/'||candidate.logical_key))
) OR (
  EXISTS(SELECT 1 FROM content_transition_file_inventories i WHERE EXISTS(SELECT 1 FROM content_transition_file_inventory_rows r WHERE r.transition_id=i.transition_id AND r.inventory_id=i.inventory_id AND (r.kind='object' AND r.identity=candidate.logical_key OR r.kind='reference' AND json_extract(r.value_json,'$.logicalKey')=candidate.logical_key)) OR EXISTS(SELECT 1 FROM json_each(i.plan_json,'$.members') m WHERE candidate.logical_key LIKE 'members/'||json_extract(m.value,'$.code')||'/backgrounds/%')) OR
  EXISTS(SELECT 1 FROM asset_file_versions v WHERE v.logical_key=candidate.logical_key AND (v.acknowledged_at IS NULL OR v.reference_committed_at IS NULL)) OR
  EXISTS(SELECT 1 FROM content_transition_file_intents i JOIN content_transitions t ON t.id=i.transition_id WHERE json_extract(i.envelope_json,'$.logicalKey')=candidate.logical_key AND (t.phase<>'complete' OR i.outcome_acknowledged=0 OR i.outcome_json IS NULL OR json_extract(i.outcome_json,'$.sideEffectReconciled')<>1))
))
    AND (NOT EXISTS(SELECT 1 FROM asset_file_versions v WHERE v.logical_key=candidate.logical_key) OR EXISTS(SELECT 1 FROM asset_file_retention_releases r WHERE r.logical_key=candidate.logical_key))
  ON CONFLICT(logical_key) DO UPDATE SET released_at=max(asset_file_retention_releases.released_at,excluded.released_at),held=0 WHERE asset_file_retention_releases.held=1;
  END;
